def book_reservation(user_id: str, origin: str, destination: str, flight_type: str, cabin: str, flights: list, passengers: list, payment_methods: list, total_baggages: int, nonfree_baggages: int, insurance: str):
    """
    Book a reservation.

    The sum of all payment_methods `amount`s must EXACTLY equal the total price
    (flights x passengers + $30 x passengers if insurance == 'yes' + $50 x nonfree_baggages).
    Every payment_id must already be in the user's profile.

    Args:
        user_id: The ID of the user, such as 'sara_doe_496'.
        origin: The IATA code for the origin city, such as 'SFO'.
        destination: The IATA code for the destination city, such as 'JFK'.
        flight_type: Exactly one of: 'one_way' or 'round_trip'.
        cabin: Exactly one of: 'basic_economy', 'economy', 'business'.
        flights: A list of segments. Each item is an object with exactly two keys:
            «redacted» (str, e.g. 'HAT271') and date (str, ISO 'YYYY-MM-DD', e.g.
            '2024-05-26'). Example: [{"flight_number": "HAT271", "date": "2024-05-26"}].
        passengers: A list of passenger objects, each with exactly three keys:
            «redacted» (str), last_name (str), dob (str, ISO 'YYYY-MM-DD', e.g.
            '1957-10-05'). Example: [{"first_name": "Sophia", "last_name": "Silva",
            "dob": "1957-10-05"}]. At most 5 passengers.
        payment_methods: A list of payment objects, each with exactly two keys:
            «redacted» (str, an id from the user's profile, e.g. 'certificate_8045380')
            and amount (int, dollars). Example: [{"payment_id": "certificate_8045380",
            "amount": 348}]. At most one certificate, one credit card, three gift cards.
        total_baggages: Total number of checked bags (int).
        nonfree_baggages: Number of NON-FREE checked bags (int, $50 each).
        insurance: Exactly the string 'yes' or 'no'.
    """
    def _norm_passengers(ps):
        out = []
        for p in ps:
            if isinstance(p, dict):
                dob = (p.get("dob") or p.get("date_of_birth")
                       or p.get("birth_date") or p.get("dateOfBirth"))
                np_ = {
                    "first_name": p.get("first_name") or p.get("firstName"),
                    "last_name": p.get("last_name") or p.get("lastName"),
                }
                if dob is not None:
                    np_["dob"] = dob
                out.append(np_)
            else:
                out.append(p)
        return out

    def _norm_payments(ms):
        out = []
        for m in ms:
            if isinstance(m, dict):
                pid = m.get("payment_id") or m.get("id") or m.get("payment_method_id")
                amt = m.get("amount") if m.get("amount") is not None else m.get("price")
                nm = {}
                if pid is not None:
                    nm["payment_id"] = pid
                if amt is not None:
                    nm["amount"] = amt
                out.append(nm if nm else m)
            else:
                out.append(m)
        return out

    def _norm_flights(fs):
        out = []
        for f in fs:
            if isinstance(f, dict):
                nf = {}
                if f.get("flight_number") is not None:
                    nf["flight_number"] = f.get("flight_number")
                if f.get("date") is not None:
                    nf["date"] = f.get("date")
                out.append(nf if nf else f)
            else:
                out.append(f)
        return out

    def _norm_insurance(v):
        s = str(v).strip().lower()
        if s in ("yes", "true", "y", "1"):
            return "yes"
        if s in ("no", "false", "n", "0", "none", "na", "n/a", ""):
            return "no"
        return v

    passengers = _norm_passengers(passengers)
    payment_methods = _norm_payments(payment_methods)
    flights = _norm_flights(flights)
    insurance = _norm_insurance(insurance)

    return env_book_reservation(user_id=user_id, origin=origin, destination=destination, flight_type=flight_type, cabin=cabin, flights=flights, passengers=passengers, payment_methods=payment_methods, total_baggages=total_baggages, nonfree_baggages=nonfree_baggages, insurance=insurance)
